using namespace std;

int main() {
    int n, k;
    cin >> n >> k;
    vector<double> p(n);
    for (int i = 0; i < n; ++i) cin >> p[i];

    vector<double> ans(n, 0.0);
    vector<double> dp(1 << n, 0.0);
    vector<double> sum_mask(1 << n, 0.0);

    auto count_bits = [](int x) {
        int cnt = 0;
        while (x) {
            cnt += x & 1;
            x >>= 1;
        }
        return cnt;
    };

    for (int mask = 0; mask < (1 << n); ++mask) {
        double s = 0.0;
        for (int i = 0; i < n; ++i) {
            if (mask & (1 << i))
                s += p[i];
        }
        sum_mask[mask] = s;
    }

    dp[0] = 1.0;
    int flag = 0;

    for (int mask = 0; mask < (1 << n); ++mask) {
        int bits_count = count_bits(mask);
        if (bits_count > k) continue;
        if (dp[mask] < 1e-100) continue;
        if (bits_count == k) flag = 1;
        double rem_sum = 1.0 - sum_mask[mask];
        if (rem_sum < 1e-6) continue;
        for (int i = 0; i < n; ++i) {
            if (mask & (1 << i)) continue;
            double move_prob = dp[mask] * p[i] / rem_sum;
            dp[mask | (1 << i)] += move_prob;
        }
    }

    if (flag == 0) {
        for (int i = 0; i < n; ++i) {
            ans[i] = (p[i] < 1e-6) ? 0.0 : 1.0;
        }
