                for (int i = 0; i < n; ++i) {
                    if (mask & (1 << i))
                        ans[i] += dp[mask];
                }
            }
        }
    }

    cout << fixed << setprecision(12);
    for (int i = 0; i < n; ++i) {
        if (i) cout << " ";
        cout << ans[i];
    }
    cout << "\n";

    return 0;
}
