import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int k = sc.nextInt();
        double[] p = new double[n];
        for (int i = 0; i < n; i++) {
            p[i] = sc.nextDouble();
        }

        double[] ans = new double[n];
        double[] dp = new double[1 << n];
        double[] sum_mask = new double[1 << n];

        // Function to count bits in an integer
        // Using built-in method Integer.bitCount for efficiency
        // No need to define a separate lambda

        for (int mask = 0; mask < (1 << n); mask++) {
            double s = 0.0;
            for (int i = 0; i < n; i++) {
                if (((mask >> i) & 1) == 1) {
                    s += p[i];
                }
            }
            sum_mask[mask] = s;
        }

        dp[0] = 1.0;
        int flag = 0;

        for (int mask = 0; mask < (1 << n); mask++) {
            int bits_count = Integer.bitCount(mask);
            if (bits_count > k) continue;
            if (dp[mask] < 1e-100) continue;
            if (bits_count == k) flag = 1;
            double rem_sum = 1.0 - sum_mask[mask];
            if (rem_sum < 1e-6) continue;
            for (int i = 0; i < n; i++) {
                if (((mask >> i) & 1) == 1) continue;
                double move_prob = dp[mask] * p[i] / rem_sum;
                dp[mask | (1 << i)] += move_prob;
            }
        }

        if (flag == 0) {
            for (int i = 0; i < n; i++) {
                ans[i] = (p[i] < 1e-6) ? 0.0 : 1.0;
            }
        } else {
            for (int mask = 0; mask < (1 << n); mask++) {
                if (Integer.bitCount(mask) == k) {
                    for (int i = 0; i < n; i++) {
                        if (((mask >> i) & 1) == 1)
                            ans[i] += dp[mask];
                    }
                }
            }
        }

        System.out.printf("%.12f", ans[0]);
        for (int i = 1; i < n; i++) {
            System.out.print(" ");
            System.out.printf("%.12f", ans[i]);
        }
        System.out.println();
        sc.close();
    }
}
